import React, { useEffect, useMemo, useState } from "react";

/**
 * Project Savings (now with 7 sub-tabs)
 * - Top "Save" button
 * - TDM Savings section (unchanged formulas)
 * - 7 Automation sub-tabs: Conformiq-Robot, Standalone (Robot/Selenium), SOA, UFT, Java, Python, Utilities
 * - Each row shows Dropdown1/2/3 + labeled fields: N, N1, PD1, C1, N2, PD2, C2, N3, Savings
 * - <Add Row> adds a row including the three dropdowns
 *
 * Notes:
 * - Field sizes are reduced via inline styles (so everything fits on one line).
 * - Logic stays the same as your previous version. :contentReference[oaicite:1]{index=1}
 */

// === Rates from Excel (kept same as earlier) ===
const RATE_R1 = 27.85; // G37
const RATE_R2 = 66.63; // G38

// ROUNDUP(x,2)
const roundUp2 = (x) => Math.ceil((Number(x) || 0) * 100) / 100;

// Create a fresh automation row with dropdowns
const mkAutoRow = () => ({
  Dropdown1: "",
  Dropdown2: "",
  Dropdown3: "",
  // “100” default inputs per your sheet conventions
  N: 100,
  N1: 100,
  N2: 100,
  N3: 100,
  PD1: 0,
  C1: 0,
  PD2: 0,
  C2: 0,
  Savings: 0,
});

// Small input style so all fields fit on one line
const sm = { width: 110, padding: "4px 6px" };
const smSel = { width: 130, padding: "4px 6px" };
const cell = { display: "flex", flexDirection: "column", gap: 2, minWidth: 130 };

export default function ProjectSavingsTab() {
  // ---- TDM Savings ---- (same formulas)
  const [tdm, setTdm] = useState({
    N: 0,        // Total deal count
    N1: 0,       // Manual Deal/day
    N2: 0,       // Avg Automation deal/day
    N3: 0,       // Number of cycles
    PD1: 0,      // = ROUNDUP(N / N1, 2)
    C1: 0,       // = PD1 * 8 * (R1 + 0.15*R2)
    PD2: 0,      // = ROUNDUP(N / N2, 2)
    C2: 0,       // = PD2 * 8 * (R1 + 0.15*R2)
    Savings: 0,  // = (C1 - C2) * N3
  });

  useEffect(() => {
    const PD1 = tdm.N1 ? roundUp2(tdm.N / tdm.N1) : 0;
    const C1 = PD1 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const PD2 = tdm.N2 ? roundUp2(tdm.N / tdm.N2) : 0;
    const C2 = PD2 * 8 * (RATE_R1 + 0.15 * RATE_R2);
    const S = (C1 - C2) * (Number(tdm.N3) || 0);
    setTdm((p) => ({ ...p, PD1, C1, PD2, C2, Savings: S }));
  }, [tdm.N, tdm.N1, tdm.N2, tdm.N3]);

  // ---- 7 Automation Sub-Tabs ----
  const SUB_TABS = [
    "Conformiq-Robot",
    "Standalone (Robot/Selenium)",
    "SOA",
    "UFT",
    "Java",
    "Python",
    "Utilities",
  ];
  const [activeSub, setActiveSub] = useState(SUB_TABS[0]);

  // Keep a separate rows array per sub-tab
  const [rowsBySub, setRowsBySub] = useState(() =>
    Object.fromEntries(SUB_TABS.map((k) => [k, [mkAutoRow()]]))
  );

  // Recompute helper (coeff 0.25 per previous automation logic)
  const recomputeAuto = (rows, coeff = 0.25) =>
    rows.map((r) => {
      const PD1 = r.N1 ? roundUp2(r.N / r.N1) : 0;
      const C1 = PD1 * 8 * (RATE_R1 + coeff * RATE_R2);
      const PD2 = r.N2 ? Number(r.N) / Number(r.N2) : 0; // previous code used raw ratio here
      const C2 = PD2 * 8 * (RATE_R1 + coeff * RATE_R2);
      const Savings = (C1 - C2) * (Number(r.N3) || 0);
      return { ...r, PD1, C1, PD2, C2, Savings };
    });

  // Update a single row / key inside the active sub-tab
  const updateRow = (subKey, idx, key, value) => {
    setRowsBySub((prev) => {
      const copy = { ...prev };
      const rows = [...copy[subKey]];
      rows[idx] = { ...rows[idx], [key]: value };
      copy[subKey] = recomputeAuto(rows);
      return copy;
    });
  };

  const addRow = (subKey) => {
    setRowsBySub((prev) => {
      const copy = { ...prev };
      copy[subKey] = recomputeAuto([...copy[subKey], mkAutoRow()]);
      return copy;
    });
  };

  // Totals across all 7 sub-tabs (if you want a grand “Automation Savings Total” like before)
  const autoSavingsTotal = useMemo(() => {
    let total = 0;
    Object.values(rowsBySub).forEach((rows) => {
      rows.forEach((r) => (total += Number(r.Savings) || 0));
    });
    return total;
  }, [rowsBySub]);

  // Dropdown options (populate from DB later)
  const DROPDOWN_OPTIONS_1 = []; // TODO
  const DROPDOWN_OPTIONS_2 = []; // TODO
  const DROPDOWN_OPTIONS_3 = []; // TODO

  // Save button handler (wire to API later)
  const onSave = () => {
    // TODO: call your API to save the current tab’s data
    console.log("Save Project Savings:", { tdm, rowsBySub });
  };

  // Render a single automation row (with labels + dropdowns)
  const renderAutoRow = (subKey, r, i) => (
    <div key={`${subKey}-${i}`} style={{ display: "flex", gap: 10, alignItems: "flex-start", flexWrap: "wrap", marginBottom: 6 }}>
      {/* Three per-row dropdowns (red) */}
      <div style={cell}>
        <label className="tab-label tab-label-green">Dropdown1</label>
        <select
          className="select-red"
          style={smSel}
          value={r.Dropdown1}
          onChange={(e) => updateRow(subKey, i, "Dropdown1", e.target.value)}
        >
          <option value="">{`<Dropdown1>`}</option>
          {DROPDOWN_OPTIONS_1.map((o) => (
            <option key={o} value={o}>{o}</option>
          ))}
        </select>
      </div>

      <div style={cell}>
        <label className="tab-label tab-label-green">Dropdown2</label>
        <select
          className="select-red"
          style={smSel}
          value={r.Dropdown2}
          onChange={(e) => updateRow(subKey, i, "Dropdown2", e.target.value)}
        >
          <option value="">{`<Dropdown2>`}</option>
          {DROPDOWN_OPTIONS_2.map((o) => (
            <option key={o} value={o}>{o}</option>
          ))}
        </select>
      </div>

      <div style={cell}>
        <label className="tab-label tab-label-green">Dropdown3</label>
        <select
          className="select-red"
          style={smSel}
          value={r.Dropdown3}
          onChange={(e) => updateRow(subKey, i, "Dropdown3", e.target.value)}
        >
          <option value="">{`<Dropdown3>`}</option>
          {DROPDOWN_OPTIONS_3.map((o) => (
            <option key={o} value={o}>{o}</option>
          ))}
        </select>
      </div>

      {/* Labeled inputs (match Excel headers) */}
      <div style={cell}>
        <label className="tab-label tab-label-green">N (Total Count)</label>
        <input className="tab-input" style={sm} type="number" value={r.N} onChange={(e) => updateRow(subKey, i, "N", Number(e.target.value))} />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N1 (Manual/day)</label>
        <input className="tab-input" style={sm} type="number" value={r.N1} onChange={(e) => updateRow(subKey, i, "N1", Number(e.target.value))} />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">PD1</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.PD1} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">C1</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.C1} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N2 (Auto/day)</label>
        <input className="tab-input" style={sm} type="number" value={r.N2} onChange={(e) => updateRow(subKey, i, "N2", Number(e.target.value))} />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">PD2</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.PD2} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">C2</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.C2} disabled />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-green">N3 (Cycles)</label>
        <input className="tab-input" style={sm} type="number" value={r.N3} onChange={(e) => updateRow(subKey, i, "N3", Number(e.target.value))} />
      </div>
      <div style={cell}>
        <label className="tab-label tab-label-orange">Savings</label>
        <input className="tab-input tab-input-orange" style={sm} value={r.Savings} disabled />
      </div>
    </div>
  );

  return (
    <div className="tab-wrap">
      {/* Save button for the (main) Project Savings tab */}
      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}>
        <button className="btn-red" onClick={onSave}>&lt;Save&gt;</button>
      </div>

      {/* ===== TDM Savings (unchanged logic) ===== */}
      <div className="tab-section tab-section-yellow">TDM Savings</div>
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "flex-start" }}>
        <div style={cell}>
          <label className="tab-label tab-label-green">N (Total deal count)</label>
          <input className="tab-input" style={sm} type="number" value={tdm.N} onChange={(e) => setTdm({ ...tdm, N: Number(e.target.value) })} />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N1 (Manual/day)</label>
          <input className="tab-input" style={sm} type="number" value={tdm.N1} onChange={(e) => setTdm({ ...tdm, N1: Number(e.target.value) })} />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">PD1 = ROUNDUP(N/N1,2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.PD1} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">C1 = PD1*8*(R1+0.15*R2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.C1} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N2 (Avg Automation/day)</label>
          <input className="tab-input" style={sm} type="number" value={tdm.N2} onChange={(e) => setTdm({ ...tdm, N2: Number(e.target.value) })} />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">PD2 = ROUNDUP(N/N2,2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.PD2} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">C2 = PD2*8*(R1+0.15*R2)</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.C2} disabled />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-green">N3 (Number of cycles)</label>
          <input className="tab-input" style={sm} type="number" value={tdm.N3} onChange={(e) => setTdm({ ...tdm, N3: Number(e.target.value) })} />
        </div>
        <div style={cell}>
          <label className="tab-label tab-label-orange">Savings = (C1 - C2) * N3</label>
          <input className="tab-input tab-input-orange" style={sm} value={tdm.Savings} disabled />
        </div>
      </div>

      {/* Optional: grand automation total like earlier */}
      <div style={{ display: "flex", gap: 12, marginTop: 10 }}>
        <div style={cell}>
          <label className="tab-label tab-label-orange">Automation Savings Total</label>
          <input className="tab-input tab-input-orange" style={sm} value={autoSavingsTotal} disabled />
        </div>
      </div>

      {/* ===== 7 Sub-Tabs for Automation stacks ===== */}
      <div className="tab-section tab-section-yellow">Automation Savings — Breakdown</div>

      {/* Sub-tab selector */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
        {SUB_TABS.map((k) => (
          <button
            key={k}
            className="btn-red"
            onClick={() => setActiveSub(k)}
            style={{ opacity: activeSub === k ? 1 : 0.65 }}
          >
            {k}
          </button>
        ))}
        <button className="btn-red" onClick={() => addRow(activeSub)}>&lt;Add Row&gt;</button>
      </div>

      {/* Rows for the active sub-tab */}
      <div>
        {rowsBySub[activeSub].map((r, i) => renderAutoRow(activeSub, r, i))}
      </div>
    </div>
  );
}
